import SwiftUI

@MainActor final class JafarMatterDeadlinesViewModel: ObservableObject { enum State { case idle, loading, loaded([MatterDeadlineDTO]), empty, failed(String) }; @Published private(set) var state: State = .idle; func load(id: String) { state = .loading; Task { guard let c = JafarClientConfiguration.configuredRemoteClient() else { state = .failed("Backend недоступен"); return }; do { let d = try await MatterClient(endpoint: c.endpoint, apiKey: c.apiKey).deadlines(id: id); state = d.isEmpty ? .empty : .loaded(d) } catch { state = .failed("Не удалось загрузить сроки") } } } }

struct MatterDeadlinesView: View { let matterID: String; @StateObject private var model = JafarMatterDeadlinesViewModel(); var body: some View { Group { switch model.state { case .idle, .loading: ProgressView("Загружаю сроки…"); case .empty: Text("По делу пока нет сохранённых сроков"); case let .failed(message): VStack { Text(message).foregroundStyle(.orange); Button("Повторить") { model.load(id: matterID) } }; case let .loaded(items): ForEach(Array(items.enumerated()), id: \.offset) { _, item in JafarCard(title: item.title) { Text(item.dueDate ?? "Дата не указана"); if let source = item.sourceText { Text("Источник: \(source)").font(.caption).foregroundStyle(JafarPalette.secondary) } } } } }.task { model.load(id: matterID) } } }
